  "derivedFrom": "subject3_q2",
  "explain": "📖 교재 근거:\n| 2등급 (청정도 분류) | 화장품 내용물이 노출되는 작업실 | 제조실, 성형실, 충전실, 내용물 보관소, 원료 칭량실, 미생물 실험실 |\n해설: 화장품 내용물이 노출되는 작업실인 제조실, 충전실, 원료 칭량실 등은 2등급 구역에 해당하므로 ④번이 옳습니다. 반면 원료 및 완제품 창고(보관소)는 4등급, 내용물이 노출되지 않는 포장실은 3등급에 속하며 내용물 배합(제조) 및 원료 칭량실은 2등급에 해당하므로 다른 선지들은 잘못되었습니다.",
