  "derivedFrom": "subject3_q3",
  "explain": "📖 교재 근거:\nCGMP·안전기준\n화장품 정의\n적용 대상\n유형별 특성\n영업 3종\n화장품제조업\n등록제\n화장품책임판매업\n등록제\n맞춤형화장품판매업\n신고제\n해설: 정답인 ③번은 「감염병의 예방 및 관리에 관한 법률」에 따른 감염병 환자(전염성 피부 질환자 포함)의 화장품 제조 업무 종사를 제한하는 기준에 부합하여 옳습니다. 반면 가벼운 감기로 평생 업무가 제한된다거나 상처 소독 없이 장갑만 착용하고 상시 참여할 수 있다는 등의 선지는 위생 점검 및 결격 기준에 맞지 않습니다.",
