  "derivedFrom": "subject3_q6",
  "explain": "📖 교재 근거:\n| DIY 키트형 | 소비자가 화장품 베이스와 부스터를 선택하여 세트 형태로 구매한 뒤, 직접 혼합하여 사용하는 방식의 화장품 |\n해설: 제공된 근거 자료에는 선입선출에 관한 내용이 포함되어 있지 않으나, 정답에 따르면 선입선출은 입고 일자가 가장 빠른 원자재를 먼저 출고하여 사용하는 방법(⑤)을 의미합니다. 따라서 입고 일자가 가장 늦은 원자재를 먼저 출고한다고 설명한 ①번 등은 옳지 않습니다.",
