  "explain": "📖 교재 근거:\n| 손 소독제 🎯 기출 | 1차 에탄올이 함유되어 세정 효과가 있음 · 물 없이도 손 소독이 가능하며, 의약외품으로 분류됨 · 알코올, 클로르헥시딘, 헥사클로로펜, 아이오도퍼 등 | 손 소독제로 소독 |\n해설: 손 소독제는 물 없이도 사용이 가능하며, 일반 비누(손 세정제)와는 다르다. 손 세정제는 흐르는 물에 비누를 사용하여 세척하는 것이고, 손 소독제는 별도의 물 없이도 소독이 가능하다.",
