  "explain": "📖 교재 근거 (L1943):\n| 안티몬 (허용한도) | 10μg/g 이하 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 유통화장품 안전관리 기준상 안티몬의 허용 한도는 10 ㎍/g 이하이므로 정답은 ②번입니다. 1 ㎍/g 이하는 수은, 5 ㎍/g 이하는 카드뮴, 20 ㎍/g 및 50 ㎍/g 이하는 납의 기준 등에 해당하므로 나머지 선지는 옳지 않습니다.",
