  "explain": "📖 교재 근거:\n| 6 | 품질이 확인되고 품질 책임자의 승인을 얻을 수 있을 때까지 재작업품은 다음 공정에 사용할 수 없고 출하할 수 없음 |\n해설: 재작업 처리는 품질 책임자의 결정과 승인이 끝난 재작업 절차서 및 기록서에 따라 실시해야 하므로 ②번이 옳습니다. 반면 재작업은 작업자가 임의로 시작할 수 없고(①), 품질 확인 및 승인 전에는 출하할 수 없으며(③), 제조 및 시험 기록 등을 충분히 남겨야 하므로(⑤) 나머지 선지는 틀렸습니다.",
