  "derivedFrom": "subject3_q22",
  "explain": "📖 교재 근거:\n| 탱크 | - 공정 단계 및 완성된 포뮬레이션 과정에서 공정 중 또는 보관용 원료를 저장하기 위해 사용함<br>- 주로 316스테인리스 스틸을 사용하며, 주형 물질 또는 거친 표면은 제품이 뭉치게 되어 화장품에는 추천하지 않음<br>- 미생물학적으로 민감하지 않은 물질이나 제품에는 유리로 안을 댄 강화유리섬유 폴리에스터와 플라스틱으로 안을 댄 탱크를 사용함<br>- 모든 용접, 결합은 가능한 한 매끄럽고 평면이어야 함<br>- 외부 표면의 코팅은 제품에 대해 저항력이 있어야 함 |\n해설: 가연성 액체 원료(에탄올 등)는 일반 원료와 혼합하여 구별 없이 보관해서는 안 되므로, ②번은 원료 보관실의 보관 환경 관리 원칙으로 옳지 않은 설명입니다. 따라서 정답은 ②번입니다.",
  "source": "유통화장품 안전관리 (316제)",
