  "explain": "📖 교재 근거:\n#### 1.6 작업장 및 제조설비\n천연화장품 또는 유기농화장품을 제조하는 작업장 및 제조설비는 교차오염이 발생하지 않도록 충분히 청소 및 세척되어야 한다.\n해설: 제조설비는 교차오염이 발생하지 않도록 관리되어야 하므로, 정제수 보관 탱크를 상시 개방하여 공기가 통하게 두면 외부로부터 오염물질이 유입되어 교차오염이 발생할 수 있어 적합하지 않은 것은 ②번입니다.",
  "source": "유통화장품 안전관리 (316제)",
  "answer": "5"
