  "explain": "📖 교재 근거:\n| 디옥산 | 100μg/g 이하 | 계면활성제 사용 제품 |\n해설: 디옥산은 계면활성제를 사용하는 제품에서 주로 발생하는 비의도적 유해 물질이므로, 계면활성제 등 원료 합성 과정에서 비의도적으로 생성되어 잔류한다는 ②번이 정답입니다. 반면 보존제 사용으로 인해 주로 검출되는 물질은 포름알데하이드이며 용기 오염, 필터 성능, 개인위생 불량 등은 디옥산의 발생 원인에 해당하지 않습니다.",
