  "explain": "📖 교재 근거:\n| 보관 구역 | • 통로는 사람과 물건이 이동하는 구역으로 사람과 물건의 이동에 불편함을 초래하거나 교차오염의 위험이 없어야 함<br>• 손상된 팔레트는 수거하여 수리 또는 폐기함<br>• 매일 바닥의 폐기물을 치워야 함<br>• 동물이나 해충이 침입하기 쉬운 환경은 개선되어야 함<br>• 용기(저장조 등)들은 닫아서 깨끗하고 정돈된 방법으로 보관해야 함 |\n해설: 플라스틱 및 중금속 폐기물을 일반 생활 쓰레기와 합쳐서 버리는 것은 적합하지 않은 폐기물 관리 방법이므로 ③이 정답입니다. 제조소 내 폐기물은 오염을 방지하기 위해 장기간 모아두거나 쌓아두지 않고, 위생적으로 관리되는 폐기물 용기 등을 통해 정기적으로 안전하게 분리·제거해야 합니다.",
