  "explain": "📖 법령 근거 (L276):\n⑤ 제조위생관리기준서는 다음 각 호의 사항이 포함되어야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제조위생관리기준서에는 작업원의 건강관리 및 위생에 관한 사항, 작업실 등의 청소 및 소독 방법 등이 포함되어야 하므로 관련 위생 관리 항목들은 이에 해당합니다. 반면, 설비 사양서 항목인 '제조 공정 중 반제품의 물리적 이송 파이프 라인 설계 도면'은 제조위생관리기준서에 포함되어야 하는 사항과 가장 거리가 멉니다.",
