  "explain": "📖 교재 근거:\n| 닦아내기 판정 | 흰 천이나 검은 천으로 설비 내부의 표면을 닦아내고, 천 표면의 잔류물 유무로 세척 결과 판정 (천은 무진포가 선호됨) |\n해설: 린스 정량법(헹굼액법)은 호스나 틈새기 등 직접 닦기 어려운 부위의 세척 판정에 적합하므로 ①번이 옳습니다. 반면 표면을 직접 문질러 닦아내는 방식은 닦아내기 판정에 해당하므로 오답입니다.",
