  "explain": "📖 교재 근거:\n4. 안전성 검사 → 중금속 검출 한도, 미생물 한도 기준, 검출 금지 병원균, 위해성 평가\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 안전성 검사 기준에 따른 유통화장품의 비소 검출 한도는 10 ㎍/g 이하이며, 시험 분석에는 원자흡광광도계(AAS) 또는 ICP-MS를 주로 사용하므로 ④번이 정답입니다. 따라서 검출 한도 수치와 분석 기기가 바르게 연결되지 않은 ①, ②, ③, ⑤번은 오답입니다.",
