  "explain": "📖 교재 근거:\n| 작업장별 소독 방법 - 칭량실 | • 관련 직원 이외의 출입을 통제하고 소독을 실시<br>• 칭량실, 제조실, 반제품 보관소, 세척실, 충전, 포장실, 원료 보관소, 원자재 보관소, 완제품 보관소 등으로 구분하여 소독방법 및 주기를 달리 함 |\n해설: 먼저 입고된 배치라도 품질 시험에서 부적합 판정이 나와 재시험 중인 원료는 부적합/보류 상태이므로 선출고가 제한되어 ⑤번이 정답입니다. 반면 수입 국가 변경, 포장 디자인 변경, 담당자 교체, 가격 인상(①~④)은 선입선출 출고를 제한하는 사유에 해당하지 않습니다.",
