  "explain": "📖 교재 근거:\n1. 유통 안전관리 기준 → 위해화장품 회수(위해성 등급·회수계획·절차), 품질관리기준\n해설: 위해화장품 위해성 등급 분류에서 비의도적으로 검출 한도를 미세하게 초과한 포름알데히드가 검출된 경우는 '나등급' 위해 사례에 해당하여 ②번이 정답입니다. 반면 사망 등 매우 심각한 부작용을 유발하거나 축적 독성이 우려되는 대량 검출 사례(①, ⑤)는 가등급에 해당하고, 단순 표기 누락이나 보고서 지연(③, ④)은 이에 해당하지 않으므로 오답입니다.",
