  "derivedFrom": "subject3_q50",
  "explain": "📖 교재 근거:\n| 가등급 (회수 기한) | 회수를 시작한 날부터 15일 이내 회수되어야 함 |\n해설: 위해화장품의 회수 기간 규정에 따라 위해성 등급이 '가등급'인 경우 회수를 시작한 날부터 15일 이내에 회수되어야 하므로 정답은 ②번입니다. 선지 ④번의 '30일 이내'는 나등급 및 다등급의 회수 기간에 해당하며, 그 외 선지들은 가등급의 회수 기간 규정과 일치하지 않습니다.",
