  "derivedFrom": "subject3_q55",
  "explain": "📖 교재 근거 (L3432):\n- 회수계획서 제출 🔖기출: 회수 대상 화장품이라는 사실을 안 날부터 5일 이내 지방식약청장에게 제출\n해설: 회수계획서는 회수 대상 화장품이라는 사실을 안 날부터 5일 이내에 지방식약청장에게 제출해야 하므로 정답은 ④입니다. 따라서 24시간 이내, 3일 이내, 7일 이내, 14일 이내로 제시된 ①, ②, ③, ⑤는 옳지 않습니다.",
  "source": "유통화장품 안전관리 (316제)",
