  "derivedFrom": "subject3_q57",
  "explain": "📖 교재 근거 (4.material-safety):\n| 니켈 (허용한도) | 눈화장용 제품 35μg/g 이하, 색조화장용 제품 30μg/g 이하, 그 밖의 제품은 10μg/g 이하 |\n해설: 제공된 정답에 따라 총호기성생균수 미생물 한도가 500개/g(mL) 이하로 차등 제한되어 엄격하게 관리되는 제품 유형은 영유아용 제품류 및 눈화장용 제품류이므로 ①번이 정답입니다. 나머지 선지인 ②, ③, ④, ⑤번의 제품류 조합은 해당 기준에 부합하지 않으므로 오답입니다.",
