  "derivedFrom": "subject3_q58",
  "explain": "📖 교재 근거 (L42):\n1. 위해화장품 회수 → 위해성 평가 → 회수계획 → 회수 → 결과보고\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 인체의 노출 빈도와 1회 사용량을 정량적으로 예측하는 단계는 위해평가 4단계 중 노출 평가(Exposure Assessment)에 해당하므로 정답은 ④번입니다. 따라서 위험성 확인, 용량-반응 평가, 위해도 결정, 안전성 모니터링을 제시한 나머지 선지(①, ②, ③, ⑤)는 이에 해당하지 않아 오답입니다.",
