  "derivedFrom": "subject3_q62",
  "explain": "📖 교재 근거:\n| 포름알데하이드 (시험법) | 액체크로마토그래프법-절대검량선법 *보존제(디아졸리디닐우레아, 디엠디엠하이단토인, 2-브로모-2-나이트로프로판-1,3-디올, 벤질헤미포름알, 소듐하이드록시메칠아미노아세테이트, 이미다졸리디닐우레아, 쿼터늄-15, 메텐아민 등)를 사용하는 화장품에서 검출될 수 있음 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품의 사용 제한 보존제 성분인 이미다졸리디닐우레아의 배합 한도는 0.6% 이하이므로 정답은 ⑤번입니다. 따라서 0.1% 이하, 0.3% 이하, 0.5% 이하, 1.0% 이하로 제시된 ①, ②, ③, ④번은 틀린 설명입니다.",
  "source": "유통화장품 안전관리 (316제)",
