  "derivedFrom": "subject3_q63",
  "explain": "📖 교재 근거 (L42):\n1. 위해화장품 회수 → 위해성 평가 → 회수계획 → 회수 → 결과보고\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 위해화장품의 위해성 평가 시 안전역(MOS)을 구하는 올바른 공식은 'MOS = NOAEL / SED'이므로 ①이 정답입니다. 분모와 분자의 위치가 바뀌었거나 LD50 등의 다른 지표를 적용한 ②, ③, ④, ⑤는 잘못된 공식입니다.",
