  "derivedFrom": "subject3_q64",
  "explain": "📖 법령 근거 (L664):\n1. 위해성 등급이 가등급인 화장품: 회수를 시작한 날부터 15일 이내\n해설: 위해성 등급이 가등급인 화장품의 경우 15일 이내로 규정되어 있으므로 ②가 정답입니다. 반면 30일 이내(④)는 위해성 등급이 나등급 또는 다등급인 화장품에 적용되며, 나머지 기간(①, ③, ⑤)은 규정에 해당하지 않아 틀린 선지입니다.",
