  "explain": "📖 교재 근거:\n| 2등급 (청정도 분류) | 화장품 내용물이 노출되는 작업실 | 제조실, 성형실, 충전실, 내용물 보관소, 원료 칭량실, 미생물 실험실 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 내용물이 노출되는 원료 칭량실이나 충전실은 2등급 청정 구역에 해당하며, 이러한 작업실은 외부 오염을 막기 위해 인접 구역보다 기압이 높은 양압(+) 상태로 유지하여 관리하므로 정답은 ②번입니다. 따라서 인접 구역보다 기압을 낮게 유지하는 음압(-) 상태로 둔다는 ①번 등은 틀린 설명입니다.",
