  "derivedFrom": "subject3_q74",
  "explain": "📖 교재 근거 (L890):\n제28조(위해화장품의 공표) ① 법 제23조의2제1항에 따라 공표명령을 받은 영업자는 지체 없이 위해 발생사실 또는 다\n해설: 위해화장품 공표 시 일반일간신문 게재를 생략할 수 있는 것은 위해성 등급이 ‘다등급’인 화장품에만 해당하므로, 가등급 위해화장품은 일간신문 등을 통한 공표가 필수적입니다(⑤번 정답). 따라서 공표가 면제되거나 임의로 생략·선택할 수 있다고 한 ①, ②, ③, ④번은 잘못된 설명입니다.",
