  "explain": "📖 법령 근거 (L1505):\n원료 품질성적서\nCGMP 4대 기준서\n제품표준서\n제조관리기준서\n품질관리기준서\n위생관리기준서\n```\n해설: 전염성 질환자의 화장품 조제 및 제조 업무 제한은 CGMP 기준서 등 위생 관리 기준을 포함하는 ⑤ '감염병의 예방 및 관리에 관한 법률 (및 CGMP 위생 관리 기준)'에 근거하므로 정답입니다. 반면 ① 화장품법, ② 식품위생법, ③ 근로기준법, ④ 민법은 해당 제한 규정에 직접적으로 부합하지 않아 오답입니다.",
