  "explain": "📖 교재 근거:\n| 내용물 감량시험 | 화장품 용기에 충전된 내용물의 건조 감량을 측정 / 마스카라, 아이라이너 또는 내용물 일부가 쉽게 취발되는 제품에 적용 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품 내용물의 산도를 기기 분석하는 시험 항목은 pH 측정 시험이므로 ⑤가 정답입니다. 미생물 한도 시험, 중금속 한도 시험, 경도 측정 시험, 용량 측정 시험(①, ②, ③, ④)은 내용물의 산도를 기기 분석하는 항목에 해당하지 않습니다.",
