  "explain": "📖 교재 근거:\n③ 완제품은 적절한 조건하의 정해진 장소에서 보관되고 주기적으로 완제품의 재고 점검이 수행되어야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 정답인 방충망(③)은 완제품 보관실 창문에 설치되어 파리, 모기 등 비래해충의 유입을 물리적으로 막아주는 망을 의미합니다. 반면 에어샤워(①), 에어커튼(②), 비닐커튼(④), 철망(⑤)은 창문에 설치하여 비래해충을 차단하는 망의 명칭으로 적절하지 않습니다.",
