  "explain": "📖 교재 근거 (L2927):\n| 1차 포장과 2차 포장 🎯 기출 | 1차 포장: 화장품 제조 시 내용물과 직접 접촉하는 포장 / 2차 포장: 1차 포장을 수용하는 1개 또는 그 이상의 포장과 보호재 및 표시의 목적으로 한 포장(첨부문서 등을 포함) |\n해설: 1차 포장은 화장품 제조 시 내용물과 직접 접촉하는 포장이므로 ②가 정답입니다. 1차 포장을 수용하는 보호재, 표시 목적의 포장 및 첨부문서 등은 1차 포장이 아닌 2차 포장에 해당합니다.",
