  "derivedFrom": "subject3_q80",
  "explain": "📖 교재 근거 (1.workspace-safety):\n| CGMP | 우수화장품 제조 및 품질관리 기준 — 3대 요소: 과오 최소화·미생물오염 방지·품질관리체계 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: CGMP에서 문서, SOP, 기준서, 규정 등을 총칭하여 일컫는 용어는 ⑤ '소프트웨어'가 맞습니다. 따라서 하드웨어나 휴먼웨어, 문서웨어, 페이퍼웨어 등은 이를 일컫는 용어가 아니므로 오답입니다.",
