  "explain": "📖 교재 근거 (L2592):\n> 한 줄 요약: 포장재(1차·2차·라벨·봉함) 입고 절차 + 안전용기 대상(아세톤·탄화수소 10%·메틸살리실레이트 5%) + 5세 미만 개봉 어려움.\n해설: 안전용기·포장 대상은 아세톤 함유 제품, 탄화수소류 10% 이상 함유 제품, 메틸살리실레이트 5% 이상 함유 제품 등이며, 일반 스킨 로션은 이에 해당하지 않으므로 정답입니다. 반면 ①, ②, ③은 안전용기·포장 대상 품목에 해당하고, ⑤ 역시 5세 미만의 어린이가 개봉하기 어렵게 설계되어야 한다는 기준에 부합하므로 틀린 선지가 아닙니다.",
