  "explain": "📖 교재 근거:\n| 소독제(시설용) | 70% 에탄올 · 50ppm 차아염소산나트륨 · 3% 크레졸수·페놀수 |\n해설: 시설용 소독제로는 에탄올, 차아염소산나트륨 등이 사용되며, 정제수는 소독제에 해당하지 않으므로 정답은 ⑤번입니다. 반면 차아염소산나트륨과 에탄올은 시설용 소독제에 해당하므로 오답입니다.",
