  "explain": "📖 교재 근거:\n• 화장품책임판매업자는 세포·조직의 채취, 검사, 배양액 제조 등을 실시한 기관에 대해 안전하고 품질이 균일한 인체 세포·조직 배양액이 제조될 수 있도록 관리·감독을 철저히 하여야 한다.\n해설: 화장품의 위해사례 보고 의무자는 화장품제조업자 및 화장품책임판매업자이므로 정답은 ①입니다. 따라서 제조업자나 책임판매업자 중 한쪽만 의무자로 보거나 소비자 또는 모든 영업자로 기재한 ②, ③, ④, ⑤는 옳지 않습니다.",
