  "explain": "📖 교재 근거 (L641):\n| 글루콘산클로르헥시딘 | • 5%를 10배 희석하여 사용<br>• 장점: 살균 효과와 항진균 효과, 피부에 대한 소독 효과<br>• 단점: 심각한 알레르기 반응 |\n해설: 제시된 보기 중 '중증 알레르기 반응(③)'은 심각한 알레르기 반응을 유발하여 인체 위험성이 가장 크므로 위해도 등급이 가장 높습니다. 반면 경미한 피부 자극(①), 일시적인 홍반(②), 사용감 불량(④), 향기 변질(⑤)은 중증 반응에 비해 위해도가 낮으므로 옳지 않습니다.",
