  "explain": "📖 법령 근거:\n| 5. 재작업 | 품질 책임자가 재작업품 합격 결정 |\n해설: CGMP 기준상 부적합(기준일탈) 판정된 제품은 폐기처분하거나 품질책임자의 결정 및 승인 하에 재작업을 실시해야 하므로 ②번이 정답입니다. 따라서 부적합 제품을 조건부 출고, 즉시 출고, 별도 포장 후 출고하거나 보류 후 재시험하는 등의 처리는 적합하지 않습니다.",
