  "explain": "📖 교재 근거:\n① 화장품의 제조와 포장에 사용되는 모든 원료 및 포장재의 부적절하고 위험한 사용, 혼합 또는 오염을 방지하기 위해 해당 물질의 검증·확인·취급 및 사용을 보장할 수 있도록 절차가 수립되어 외부로부터 공급된 원료 및 포장재는 규정된 완제품 품질합격 판정 기준을 충족시켜야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품 제조 시 원료 및 제품의 부적절한 사용, 혼합 또는 오염을 방지할 수 있도록 절차를 수립하여 취급해야 하므로, 동일 설비에서 동시에 여러 제품을 제조하는 것(③)은 교차 오염을 유발할 수 있어 적절하지 않습니다. 따라서 원료의 분리 보관이나 설비의 세정·소독 등 혼합과 오염을 방지하는 조치와 거리가 먼 ③번이 정답입니다.",
