  "explain": "📖 교재 근거:\n| 품질관리 책임자 / 행정기관 담당자 | 기준·판정·법 근거 제시 | 냉정·정확한 권위자. 각색해도 대사의 사실은 원문 유지. |\n해설: 품질관리책임자는 기준과 판정을 제시하는 주체이므로, 제조 시 침전물이 발생했을 때는 원인을 조사하고 시정조치를 거쳐 품질관리책임자의 판정을 받아야 합니다. 따라서 책임자의 공식적인 판정 없이 임의로 처리하거나 제품을 그대로 출고·할인 판매하도록 한 ①, ②, ③, ④는 옳지 않습니다.",
