  "explain": "📖 교재 근거:\n| 크로스컷트시험 🎯 기출 | 화장품 용기의 포장재료인 유리, 금속, 플라스틱의 유·무기 코팅막 및 도금의 밀착력 측정 / 규정된 점착테이프와 압착 장치를 이용하여 코팅막, 도금의 박리 여부를 확인 내어 압착 및 방치한 후 떼어냄 |\n해설: 화장품 제조 시 포장재 관리는 내구성·밀착력 시험 등을 통한 품질 기준 설정과 검수, 보관 조건 관리 및 불량 방지가 중심이 되므로 '포장재의 재활용 여부 확인'은 관리 기준으로 적절하지 않습니다. 따라서 정답은 ③이며, ①, ②, ④, ⑤는 포장재의 품질과 안전성을 확보하기 위해 요구되는 관리 항목에 해당합니다.",
