  "explain": "📖 법령 근거 (L421):\n① 법 제4조의2제1항 및 이 규칙 제10조의2제2항에 따라 화장품의 표시ㆍ광고를 하려는 화장품책임판매업자는 법 제4조의2제1항제1호부터 제3호까지의 규정에 따른 제품별 안전성 자료 모두를 미리 작성해야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 소비자 기호도 조사는 제품에 대한 선호도를 파악하는 조사로 화장품의 안전성을 검증하는 시험 항목에 해당하지 않아 정답입니다. 반면 피부 감작(알레르기) 시험, 안점막 자극 시험, 경구 독성 시험, 피부 1차 자극 시험(②~⑤)은 화장품의 인체 안전성을 확인하기 위한 시험 항목에 해당하므로 오답입니다.",
