  "explain": "📖 교재 근거:\n| 2등급 (청정도 분류) | 화장품 내용물이 노출되는 작업실 | 제조실, 성형실, 충전실, 내용물 보관소, 원료 칭량실, 미생물 실험실 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품 제조 시 작업 지시서(SOP)의 역할에 '제품의 판매 전략 수립'은 해당하지 않으므로 ③이 정답입니다. 반면 작업의 표준화, 품질의 균일성 확보, 작업 오류 방지, 작업자의 안전 확보는 작업 지시서의 역할에 해당하므로 오답입니다.",
