  "derivedFrom": "subject3_q108",
  "explain": "📖 교재 근거 (L2982):\n② 가용화 공정 또는 유화 공정 시 제조 온도와 설정 온도의 차이가 생기는 경우\n해설: 유화 공정은 제조 온도가 설정 온도보다 지나치게 높을 경우 유화제의 HLB가 변해 전상 온도 이상에서 상이 뒤바뀌면서 유화 안정성에 문제가 생기고 외관, 점도, 냄새, 색상 등이 변할 수 있으므로 온도 관리가 가장 중요합니다. 따라서 유화 안정성에 영향을 주는 온도 관리가 핵심인 공정은 ① 유화 공정이며, 혼합·교반, 충전, 포장, 라벨링 공정(②, ③, ④, ⑤)은 이에 해당하지 않습니다.",
  "source": "유통화장품 안전관리 (316제)",
