  "explain": "📖 법령 근거:\n> - 온도·습도·차광: 필요한 항목 설정 / 안정성시험 결과, 제품표준서 등을 토대로 제품마다 설정\n해설: 화장품의 보관 조건 및 유효기간 설정 등은 안정성시험 결과 등을 토대로 제품마다 설정하므로 ⑤번이 정답입니다. 마케팅 부서의 결정이나 원료 공급자의 권장, 설문 조사 등(①~④)은 객관적인 시험 결과에 근거한 기준이 아니므로 적절하지 않습니다.",
