  "derivedFrom": "subject3_q114",
  "explain": "📖 교재 근거:\n| 제조단위 또는 뱃치 | 하나의 공정이나 일련의 공정으로 제조되어 균질성을 갖는 화장품의 일정한 분량 |\n해설: 공정관리는 제조공정 중 적합 판정 기준의 충족을 보증하기 위해 공정을 모니터링하거나 조정하는 작업이므로, 제조 공정 중 품질 이상을 조기에 발견하는 것이 목적입니다. 따라서 완제품의 품질만 확인하거나 시장 가격 조사, 판매 가격 결정, 소비자 기호 파악을 목적으로 하는 나머지 선지는 옳지 않습니다.",
