  "derivedFrom": "subject3_q115",
  "explain": "📖 교재 근거:\n### (1) 우수화장품 제조 및 품질관리 기준(CGMP: Cosmetic Good Manufacturing Practice)\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품 제조 시 우수한 화장품을 제조·공급하기 위한 제조 환경 관리에는 폐수 처리, 폐기물 처리, 소음 관리, 작업 환경의 온습도 관리 등이 포함됩니다. 반면 ④번 ‘제품의 광고 전략’은 제조 시 수행하는 환경 관리 항목에 해당하지 않으므로 정답입니다.",
