  "derivedFrom": "subject3_q117",
  "explain": "📖 교재 근거:\n> 문제 3. 화장품 제조 설비에서 가장 널리 사용되는 스테인리스 스틸은?\n> ① 304 ② 316 ③ 430 ④ 201\n>\n> 정답: ② 316 (단, 304도 널리 사용됨)\n> 해설: 탱크, 필터, 이송파이프, 충전기 등에서 316 스테인리스가 선호되며, 304도 함께 사용된다. 316은 304보다 부식에 강하다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
