  "explain": "📖 법령 근거 (L402):\n③ 제2항에 따라 보고서를 받은 식품의약품안전평가원장은 제1항에 따른 요건을 확인한 후 다음 각 호의 사항을 기능성화장품의 보고대장에 적어야 한다.<개정 2013. 3. 23., 2019. 3. 14.>\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제시된 기준에 따르면 소비자의 신상 정보는 화장품 보고 내용에 포함되어야 할 사항에 해당하지 않으므로 ④번이 정답입니다. 반면 제품의 명칭 및 제조번호, 위해 증상, 위해 발생 일자, 위해 발생 경위는 보고 대상에 해당하므로 오답 선지입니다.",
