  "explain": "📖 교재 근거:\n| 2등급 (청정도 분류) | 화장품 내용물이 노출되는 작업실 | 제조실, 성형실, 충전실, 내용물 보관소, 원료 칭량실, 미생물 실험실 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제시된 기준에 따르면 원료 보관소는 청정도 4등급의 일반 작업실(대상시설)로 분류되어 실내에서 관리되어야 하므로, 원료를 야외에 보관할 수 있다고 한 ②번은 적절하지 않은 설명입니다.",
