  "explain": "📖 교재 근거:\n| 게이지와 미터기 | - 온도, 압력, 흐름, 점도, pH, 속도, 부피 등 화장품의 특성을 측정 및 기록하기 위해 사용함<br>- 제품과 직접 접하는 게이지와 미터의 적절한 기능에 영향을 주지 않아야 하며, 대부분 원료와 직접 접하지 않도록 분리 장치를 제공함 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제공된 정답에 따라 화장품 제조 설비의 세정 기록에는 세정 방법, 세정 담당자, 세정 후 확인 결과, 세정 일자 등이 포함되며, 세정 비용 청구액은 세정 기록에 해당하지 않으므로 ⑤번이 옳지 않습니다.",
