  "explain": "📖 교재 근거:\n| 필터, 여과기, 체 | - 화장품 원료와 완제품의 입자 크기를 작게 하고, 덩어리 모양을 깨고, 불순물을 제거하기 위해 사용<br>- 스테인리스 스틸과 비반응성 섬유이며, 316스테인리스는 제품 제조 시 선호 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 마케팅 효과 분석은 화장품 제조 시 제품 특성을 확인하는 완제품 검사 항목에 해당하지 않으므로 ③이 정답입니다. 반면 관능 시험, 미생물 시험, pH 시험, 중금속 시험은 제품의 특성과 품질을 확인하기 위한 완제품 검사 항목에 해당합니다.",
