  "derivedFrom": "subject3_q134",
  "explain": "📖 교재 근거:\n| 2등급 (청정도 분류) | 화장품 내용물이 노출되는 작업실 | 제조실, 성형실, 충전실, 내용물 보관소, 원료 칭량실, 미생물 실험실 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 정답은 ⑤번으로, 작업자의 퇴직금 계산 방법은 화장품 제조를 위한 작업 지시서(SOP)에 포함되는 내용에 해당하지 않습니다. 반면 작업 절차(①), 사용 설비 및 기구(②), 작업 상의 주의 사항(③), 작업 후의 기록 사항(④)은 작업 지시서에 포함되는 내용이므로 오답입니다.",
  "source": "유통화장품 안전관리 (316제)",
  "answer": "4"
