  "explain": "📖 교재 근거 (L840):\nroot((CGMP<br/>우수화장품 제조 및<br/>품질관리 기준<br/>제2024-46호))\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품 제조 시 위생 관리는 작업자 개인이나 특정 담당자에게만 국한되는 것이 아니라 최고경영자의 책임을 포함한 전 직원 공동의 책임이므로 ③번이 정답입니다. 따라서 위생 관리 책임을 작업자 개인(①), 제조 담당자(②), 대표이사(④), 품질관리책임자(⑤) 등 특정 대상에게만 한정하는 선지는 옳지 않습니다.",
