  "explain": "📖 교재 근거:\n> 한 줄 요약: 칭량(전자저울·메스실린더) + 혼합(호모게나이저·디스퍼·오버헤드스터러) + 소분(스패츌러·디스펜서·피펫) + 측정(pH미터·점도계·경도계) + 살균(자외선 살균기).\n해설: 화장품 제조 시 설비의 교정 대상은 원료의 칭량에 쓰이는 저울이나 측정을 위한 pH 미터, 온도계, 압력계와 같은 측정 설비들이 해당하므로 작업용 의자는 교정 대상이 아닙니다. 따라서 ①, ②, ③, ④는 교정 대상 설비에 해당하여 오답이며, ⑤가 정답입니다.",
