  "explain": "📖 법령 근거 (L436):\n② 실태조사에는 다음 각 호의 사항이 포함되어야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: CGMP 기준상 불만 처리 절차에 '불만 접수자의 인사 평가'는 포함되어야 할 사항에 해당하지 않으므로 ⑤가 정답입니다. 반면 불만의 접수 및 기록, 불만 원인의 조사, 시정조치의 실시, 조치 결과의 기록 및 보존(①~④)은 불만 처리 절차에 포함되는 사항이므로 틀린 선지입니다.",
