  "explain": "📖 교재 근거:\n| 2등급 (청정도 분류) | 화장품 내용물이 노출되는 작업실 | 제조실, 성형실, 충전실, 내용물 보관소, 원료 칭량실, 미생물 실험실 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품 제조 시 청정도 측정은 정기적으로(분기 또는 반기) 실시하여 관리 기준을 준수해야 하므로 ③번이 정답입니다. 따라서 1년마다(①), 6개월마다(②), 필요시에만 측정(④)하거나 측정이 불필요(⑤)하다는 선지는 모두 옳지 않습니다.",
