  "explain": "📖 교재 근거:\n| 크로스컷트시험 🎯 기출 | 화장품 용기의 포장재료인 유리, 금속, 플라스틱의 유·무기 코팅막 및 도금의 밀착력 측정 / 규정된 점착테이프와 압착 장치를 이용하여 코팅막, 도금의 박리 여부를 확인 내어 압착 및 방치한 후 떼어냄 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품 제조 시 포장재 검수는 포장재 자체의 품질과 상태를 점검하는 과정이므로, '포장재 제조업체의 주가 확인'은 검수 항목에 해당하지 않아 ①이 정답입니다. 반면 포장재의 수량, 외관, 규격 적합성, 품명 확인(②, ③, ④, ⑤)은 포장재를 정상적으로 수령하고 품질을 검수하기 위해 확인하는 항목이므로 오답입니다.",
