  "explain": "📖 법령 근거 (CGMP_별표2_실시상황평가표):\n| 아. 문서의 기록은 작업자가 작업과 동시에 지울 수 없는 잉크로작성 하였는가? |  |  |\n해설: 규범에 따르면 문서의 기록은 작업자가 작업과 동시에 작성하도록 되어 있으므로 ②번이 정답입니다. 따라서 작업 완료 후 일괄 작성하거나 작업 전 사전 작성, 또는 주·월 단위로 작성한다는 선지들은 잘못되었습니다.",
