  "explain": "📖 교재 근거 (L325):\n#### (1) 기준일탈 제품 처리 과정\n해설: CGMP 기준상 기준일탈 제품은 '기준일탈 발생 → 조사 → 격리 보관 → 폐기/재작업/반품'의 순서로 처리해야 하므로 ①번이 옳습니다. 따라서 조사나 격리 보관 과정을 거치지 않고 폐기, 재작업, 반품 등을 즉시 진행하는 순서로 설명된 나머지 선지들은 모두 틀렸습니다.",
