  "explain": "📖 교재 근거:\n① 재작업의 정의: 적합판정 기준을 벗어난 완제품 또는 벌크제품을 재처리하여 품질이 적합한 범위에 들어오도록 하는 작업이다.\n해설: CGMP 기준상 재작업은 적합판정 기준을 벗어난 완제품 또는 벌크제품을 재처리하여 품질이 적합한 범위에 들어오도록 하는 작업을 의미하므로 ①번이 정답입니다. 따라서 새로운 원료로 제품을 다시 제조하거나 포장 교체, 설비 세척, 회수 제품 수리 등을 의미하는 ②, ③, ④, ⑤번은 재작업의 정의에 해당하지 않습니다.",
