  "explain": "📖 교재 근거 (L2224):\n> 참고 - 품질 책임자의 이행 업무\n> - 품질에 관련된 모든 문서와 절차의 검토 및 승인\n> - 품질검사가 규정된 절차에 따라 진행되는지 확인\n해설: 품질 책임자의 이행 업무에는 품질 관련 문서·절차의 검토 및 승인, 품질검사 진행 확인, 일탈 조사 및 기록, 적합 판정된 원자재·제품의 출고 여부 결정이 포함되므로 ①, ②, ③, ④는 모두 올바른 설명입니다. 반면 제조 설비의 직접 조작 및 생산 관리는 품질 책임자의 이행 업무에 해당하지 않으므로 ⑤가 정답입니다.",
