  "explain": "📖 교재 근거 (L1943):\n| 안티몬 (허용한도) | 10μg/g 이하 |\n해설: 유통화장품 안전성 기준에 따르면 안티몬의 허용 한도는 10μg/g 이하이므로 정답은 ①입니다. 따라서 5, 20, 30, 50을 제시한 ②, ③, ④, ⑤는 안티몬의 허용 한도 기준과 일치하지 않아 오답입니다.",
