  "explain": "📖 교재 근거:\n| 불검출 균 | 대장균·녹농균·황색포도상구균 — 모든 화장품류 |\n해설: 화장품 미생물 한도 기준에서 불검출되어야 하는 균은 대장균, 녹농균, 황색포도상구균이므로 빈칸에 들어갈 미생물은 ② 황색포도상구균입니다. 따라서 살모넬라균, 리스테리아균, 크로노박터균, 아스페르길루스균(①, ③, ④, ⑤)은 해당 불검출 기준에 명시된 미생물이 아니므로 오답입니다.",
