  "explain": "📖 교재 근거:\n> 해설: 차아염소산나트륨액은 50ppm 락스로 당일 조제하여 사용 후 전량 폐기해야 한다. 강한 살균력과 경제성이 장점이나 냄새가 강하고 잔류성·부식성이 있다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
