  "explain": "📖 교재 근거 (L2817):\n| (2) 포장재의 개봉 후 사용기간 확인·판정 🎯 기출 | '개봉 후 사용기간'이라는 문자와 '○○월' 또는 '○○개월'을 조합하여 기재·표시하거나, 개봉 후 사용기간을 나타내는 심벌과 기간을 기재·표시할 수 있다(개봉 후 사용기간을 표시하는 경우에는 제조연월일, 사용기한을 병기하여 표기함). |\n해설: 개봉 후 사용기간은 '개봉 후 사용기간'이라는 문자와 '○○월' 또는 '○○개월'을 조합하여 기재·표시할 수 있으므로 ②가 옳습니다. 한편 개봉 후 사용기간을 나타내는 심벌과 기간을 함께 기재·표시할 수 있으며, 이를 표시할 때는 제조연월일과 사용기한을 병기해야 하므로 ③, ④ 등은 틀린 설명입니다.",
