  "explain": "📖 교재 근거 (L526):\n| 카드뮴 허용한도 | 5μg/g 이하 |\n해설: 유통화장품 안전기준상 카드뮴의 허용 한도는 5㎍/g 이하이므로 정답은 ④번입니다. 따라서 10, 20, 30, 50㎍/g을 제시한 나머지 선지(①, ②, ③, ⑤)는 허용 기준과 일치하지 않습니다.",
