  "explain": "📖 교재 근거:\n| 페놀 화합물: 파라벤, 페녹시에탄올, 페닐에탄올 등 아닐리드 | 레시틴, 폴리솔베이트80, 지방알코올의 에틸렌 옥사이드 축합물(condensate), 비이온성 계면활성제 |\n해설: 제시된 내용 중 관련 성분으로 '에틸렌 옥사이드'가 언급되므로 빈칸에 들어갈 화학물질은 ①번 에틸렌이 올바른 답입니다. 따라서 프로필렌, 부틸렌, 스티렌, 아세틸렌(②~⑤)은 해당하지 않는 오답입니다.",
