  "explain": "📖 교재 근거:\n| 손 소독제 🎯 기출 | 1차 에탄올이 함유되어 세정 효과가 있음 · 물 없이도 손 소독이 가능하며, 의약외품으로 분류됨 · 알코올, 클로르헥시딘, 헥사클로로펜, 아이오도퍼 등 | 손 소독제로 소독 |\n해설: 소독 및 세정 효과가 있는 알코올 성분으로 에탄올이 제시되어 있으므로 빈칸에 들어갈 알맞은 명칭은 ② 에탄올입니다. 메탄올, 이소프로판올, 포름알데히드, 과산화수소 등의 다른 선지는 해당 설명에 부합하지 않는 성분입니다.",
