  "derivedFrom": "subject3_q187",
  "explain": "📖 법령 근거 (L665):\n2. 위해성 등급이 나등급 또는 다등급인 화장품: 회수를 시작한 날부터 30일 이내\n화장품법 시행규칙\n해설: 화장품법 시행규칙에 따르면 위해성 등급이 나등급 또는 다등급인 화장품의 회수 기간은 회수를 시작한 날부터 30일 이내로 기재해야 하므로 정답은 ③입니다. 15일 이내는 위해성 등급이 가등급인 화장품에 해당하며, 나머지 선지(①, ②, ④, ⑤)는 나등급 또는 다등급의 회수 기간에 부합하지 않습니다.",
