  "explain": "📖 교재 근거:\n| 니켈 (허용한도) | 눈화장용 제품 35μg/g 이하, 색조화장용 제품 30μg/g 이하, 그 밖의 제품은 10μg/g 이하 |\n해설: 화장품 배합 제한 성분 중 페녹시에탄올의 보존 한도는 1.0% 이하이므로 빈칸에 들어갈 알맞은 값은 ①입니다. 따라서 1.0%가 아닌 0.1%, 0.5%, 2.0%, 5.0%를 제시한 ②, ③, ④, ⑤는 모두 오답입니다.",
