  "explain": "📖 교재 근거:\n> 한 줄 요약: 적정 조건(조명·온습도) + 상태별 구분 보관 + 선입선출 + 파레트 표시 4요소.\n해설: 완제품 보관 시 바닥이나 벽에 닿지 않도록 받쳐두는 나무 또는 플라스틱 판 형태의 보관 관리 자재는 파레트이므로 ②가 정답입니다. 선반, 컨테이너, 랙, 크레이트는 설명과 일치하지 않는 자재이므로 정답이 아닙니다.",
