  "explain": "📖 교재 근거:\n> 한 줄 요약: 세제 7대 성분(계면활성제·살균제·금속이온봉쇄제·유기폴리머·용제·연마제·표백) + 요구조건 5가지 + 작업장별 청소 주기.\n해설: EDTA-2Na와 같이 미량 금속의 활성을 억제하여 변색을 막는 성분은 킬레이트제인 금속이온봉쇄제에 해당하므로 정답은 ③번입니다. 반면 항산화제, 보존제, 계면활성제, 증점제는 킬레이트(금속이온봉쇄)제의 역할과 일치하지 않습니다.",
