  "explain": "📖 교재 근거:\n> 출처: 우수화장품 제조 및 품질관리기준(식품의약품안전처고시)(제2024-46호)(20240822).md\n해설: 우수화장품 제조 및 품질관리기준에 따라 감염병 환자나 피부 전염성 질환이 있는 사람은 화장품 ‘제조’ 업무에 종사할 수 없으므로 정답은 ①번입니다. 따라서 판매, 포장, 유통, 보관 업무를 제시한 나머지 선지는 옳지 않습니다.",
