  "explain": "📖 교재 근거:\n| 게이지와 미터기 | - 온도, 압력, 흐름, 점도, pH, 속도, 부피 등 화장품의 특성을 측정 및 기록하기 위해 사용함<br>- 제품과 직접 접하는 게이지와 미터의 적절한 기능에 영향을 주지 않아야 하며, 대부분 원료와 직접 접하지 않도록 분리 장치를 제공함 |\n해설: 내용물의 수소이온농도를 측정하는 화장품 특성 시험 항목은 pH 시험이므로 ②가 정답입니다. 나머지 선지인 비중, 점도, 굴절률, 수분함량은 수소이온농도를 측정하는 시험 항목이 아니므로 오답입니다.",
