  "explain": "📖 교재 근거:\n| 크로스컷 시험 🎯 기출 | 화장품 용기의 포장재료인 유리, 금속, 플라스틱의 유·무기 코팅막 및 도금의 밀착력 측정 / 규정된 점착테이프와 압착 장치를 이용하여 코팅막, 도금의 박리 여부를 확인 |\n해설: 화장품 용기 포장재료인 유리, 금속, 플라스틱의 유·무기 코팅막 및 도금의 밀착력을 측정하는 시험은 크로스컷 시험이므로 정답은 ③번입니다. 반면 낙하시험은 용기의 낙하에 따른 파손 및 분리 여부 등을 측정하고, 접착력시험은 인쇄된 문자나 라미네이팅 등의 밀착성을 측정하는 시험이므로 적절하지 않습니다.",
