  "explain": "📖 교재 근거:\n사용기한 확인\n포장용기 종류\n밀폐 용기\n기밀 용기\n밀봉 용기\n차광 용기\n안전용기\n아세톤 함유\n탄화수소 10% 이상\n메틸살리실레이트 5% 이상\n포장 시험 방법\n해설: 발문에서 차광 여부를 기준으로 빛에 의해 쉽게 분해되는 물질의 보관 용기를 묻고 있으므로 빈칸에는 ② '차광'이 들어가는 것이 가장 적절합니다. ① 밀봉은 포장용기 종류 중 하나이나 차광 여부 기준에 부합하지 않으며, ③ 냉장, ④ 건조, ⑤ 방습 역시 적절하지 않은 오답입니다.",
