  "explain": "📖 교재 근거:\n> 출처: 우수화장품 제조 및 품질관리기준(식품의약품안전처고시)(제2024-46호)(20240822).md\n해설: 우수화장품 제조 및 품질관리기준의 작업장 위생관리에 따라 전염성 감염병 환자나 피부 질환이 있는 사람은 화장품 제조 업무에 종사할 수 없으므로 정답은 ③번입니다. 따라서 판매, 포장, 운반, 보관을 제시한 ①, ②, ④, ⑤번은 빈칸에 들어갈 내용으로 적절하지 않습니다.",
