  "explain": "📖 교재 근거:\n| 닦아내기 판정 | 흰/검은 천으로 표면 닦아 잔류물 확인 | 설비 내부 표면 | 무진포 선호 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 설비 세척 검증 시 좁은 배관이나 틈새기 등의 잔류물 확인을 위해 최종 헹굼액을 채취하여 분석하는 린스 정량법을 한글로는 '헹굼액(최종세척액)'법이라고 부르므로 정답은 ④입니다. 따라서 세척액, 소독액, 배양액, 추출액을 언급한 ①, ②, ③, ⑤는 최종 헹굼(린스)액을 채취하는 명칭으로 적절하지 않습니다.",
