  "stem": "위해화장품 위해성 등급 분류 중 화장품의 사용으로 사망이나 완치되기 어려운 중증의 부작용을 일으킬 우려가 있는 위해화장품은 ________등급에 속한다. 위 빈 칸에 들어갈 옳은 것을 모두 고른 것은?",
