  "explain": "📖 교재 근거:\n| 재작업 | 적합판정 기준 벗어난 완제품·벌크를 재처리하여 적합 범위로 |\n해설: '재작업'은 적합판정 기준을 벗어난 대상을 재처리하여 적합 범위로 수정하는 가공 작업을 의미하므로 ④번이 정답입니다. 따라서 제품을 버리는 폐기(②)나 재포장(①), 재사용(③), 출하(⑤)는 기준을 벗어난 대상을 재처리해 적합하도록 수정하는 작업의 정의에 부합하지 않습니다.",
