  "explain": "📖 교재 근거 (L2646):\n• 일회용 제품, 용기 입구 부분이 펌프 또는 방아쇠로 작동되는 분무용기 제품, 압축 분무용기 제품(에어로졸 제품 등)은 대상에서 제외함\n해설: 일회용 제품, 펌프/방아쇠 분무용기, 에어로졸 제품은 안전용기·포장 대상에서 제외된다. 아세톤 함유 리무버, 탄화수소 10% 이상 어린이용 오일, 메틸살리실레이트 5% 이상 제품은 안전용기 대상이다.",
