  "explain": "📖 교재 근거:\n> 참고 - 완제품의 관리 항목: 보관, 검체 채취, 보관용 검체, 제품 시험, 합격·출하 판정, 출하, 재고 관리, 반품\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 완제품 보관 창고에서 유인 포획용으로 설치하는 조명 기구는 포충등이므로 정답은 ④입니다. 유도등, 살균등, 자외선등, 형광등은 유인 포획용 조명 기구가 아니므로 적절하지 않습니다.",
