  "derivedFrom": "subject3_q234",
  "explain": "📖 교재 근거:\n| 기준일탈 | 규정된 합격 판정 기준에 일치하지 않는 검사·측정·시험 결과 |\n해설: 규정된 합격 판정 기준에 일치하지 않는 검사·측정·시험 결과를 '기준일탈'이라고 하므로, 기준일탈 발생 시 작성해야 하는 보고서의 명칭은 '기준일탈(OOS)' 보고서입니다. 따라서 ⑤번이 정답이며, CGMP 규정을 벗어난 행위를 뜻하는 일탈(Deviation)이나 기준초과, 부적합 등은 해당 보고서의 명칭으로 적절하지 않습니다.",
  "source": "유통화장품 안전관리 (316제)",
