  "explain": "📖 교재 근거:\n① 포장재는 정기적으로 재고조사를 실시하여야 하며, 중대한 위반품이 발견되었을 경우에는 일탈처리를 한다.\n해설: 사망이나 중증 질환과 같이 심각한 위해가 발생한 경우를 가리키므로 빈칸에 들어갈 가장 적절한 용어는 '중대한'이며 따라서 정답은 ①입니다. 반면 경미한, 일반적인, 특수한, 가벼운을 제시한 ②, ③, ④, ⑤는 해당 상황에 부합하지 않아 오답입니다.",
