  "explain": "📖 법령 근거:\n| 변경관리 | 모든 제조, 관리 및 보관된 제품이 규정된 적합 판정 기준에 일치하도록 보장하기 위해 우수화장품 제조 및 품질관리기준(CGMP)이 적용되는 모든 활동을 내부 조직의 책임하에 계획하여 변경하는 것 |\n해설: CGMP 기준상 시험 결과 등이 규정된 기준을 충족하여 판정하는 것을 ‘적합’ 판정이라고 하므로 정답은 ①입니다. 따라서 기준을 충족하지 못하거나 그 외의 상태를 의미하는 부적합, 보류, 조건부, 특례는 빈칸에 들어갈 말로 적절하지 않습니다.",
