  "explain": "📖 법령 근거 (L173):\n다. 감사결과가 기록되어 경영책임자 및 피감사부서의 책임자에게 공유되고 감사 중에 발견된 결함에 대하여 시정조치가 이뤄지고 있는가?\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 품질관리시스템의 적절성과 유효성을 평가하기 위해 경영자가 직접 실시하는 활동이므로 빈칸에 들어갈 말은 '경영자' 검토입니다. 따라서 정답은 ③이며, 품질관리책임자나 제조책임자, 외부감사자, 정부관계자가 주체가 아니므로 ①, ②, ④, ⑤는 옳지 않습니다.",
