  "explain": "📖 법령 근거 (L2696):\n| 완제품 | 출하를 위해 제품의 포장 및 첨부문서에 표시하는 공정 등을 포함한 모든 제조 공정이 완료된 화장품 |\n해설: 완제품은 출하를 위해 모든 제조 공정이 완료된 화장품을 의미하므로 완제품의 품질을 확인하는 최종 검사는 ‘완제품(출하)’ 검사가 가장 적절합니다. 반면 원료는 벌크제품의 제조에 투입하거나 포함되는 물질을 뜻하므로 최종 검사에 해당하지 않습니다.",
