  "explain": "📖 법령 근거:\n> 4과목은 맞춤형화장품 실무 중심 과목입니다. 맞춤형화장품 2유형(혼합형·소분형), 안전성시험 9종, 안정성시험 4종, 피부 구조(표피 5층·진피·피하조직), 관능평가 방법, 제품 상담·안내, 혼합·소분·충진·포장 공정을 정확히 암기해야 합니다.\n해설: 화장품 제조 시 제품의 사용기한을 설정하기 위해 실시하는 시험은 안정성 시험이므로 정답은 ③번입니다. 반면 ①번 안전성 시험 등은 사용기한을 설정하는 목적의 시험과 구별되므로 올바르지 않습니다.",
