  "explain": "📖 법령 근거:\n| 변경관리 | 모든 제조, 관리 및 보관된 제품이 규정된 적합 판정 기준에 일치하도록 보장하기 위해 우수화장품 제조 및 품질관리기준(CGMP)이 적용되는 모든 활동을 내부 조직의 책임하에 계획하여 변경하는 것 |\n해설: CGMP 기준에서 제조 및 품질관리가 효과적으로 실행되고 목적 달성에 적합한지 여부를 결정하기 위해 회사 내 자격이 있는 직원에 의해 행해지는 조사는 ‘내부감사’이므로 빈칸에 들어갈 말은 ‘내부’입니다. 따라서 외부, 정부, 제3자, 자발적 감사라고 제시된 나머지 선지는 올바르지 않습니다.",
  "source": "유통화장품 안전관리 (316제)",
  "answer": "3"
