  "explain": "📖 교재 근거:\n| P/F (Pre Filter) | 5㎛ 제거, 9mmAq. 세척 후 3~4회 재사용. 1차 여과. |\n해설: 세척 후 3~4회 재사용이 가능하며 1차 여과를 담당하는 것은 프리 필터(P/F)이다. 헤파 필터는 최종 여과 장치로서 0.3㎛ 입자를 99.97% 제거한다.",
