  "explain": "📖 교재 근거:\n| 불용 처리 | 부품 수급 불가, 수리비용 > 신규 도입비용, 신뢰성 지속적 저하. |\n해설: 불용 처리는 수리비용이 신규 도입비용보다 크거나, 부품 수급이 불가하거나, 신뢰성이 지속적으로 저하될 때 수행한다. 따라서 수리비용이 신규 도입비용을 초과하는 경우 불용 처리하는 것이 맞다.",
  "source": "유통화장품 안전관리 (316제)",
